import { MILLISECONDS_PER_SECOND, parseDuration } from "./duration.ts";

const MIN_TTL_MS = 5 * MILLISECONDS_PER_SECOND;
const MAX_TTL_MS = 24 * 60 * 60 * MILLISECONDS_PER_SECOND;

/** Returns an error message for an unusable cache TTL, or null when the TTL is fine. */
export function validateTtl(ttl: string): string | null {
  let milliseconds: number;
  try {
    milliseconds = parseDuration(ttl);
  } catch {
    return `ttl "${ttl}" is not a duration`;
  }
  if (milliseconds < MIN_TTL_MS) {
    return `ttl "${ttl}" is below the minimum of 5s`;
  }
  if (milliseconds > MAX_TTL_MS) {
    return `ttl "${ttl}" exceeds the maximum of 1d`;
  }
  return null;
}

